import task.group.presentation.query.response.*

/** 서비스 소유 OpenAPI와 조회 진입점 계약(POL-CQRS-004). */
@ApiResponses(
  ApiResponse(
    responseCode = "400",
    description = "VALIDATION_FAILED",
    content =
      [
        Content(
          mediaType = "application/problem+json",
          schema = Schema(implementation = GroupProblemResponse::class),
        )
      ],
  ),
  ApiResponse(
    responseCode = "403",
    description = "INTERNAL_ACCESS_DENIED",
    content =
      [
        Content(
          mediaType = "application/problem+json",
          schema = Schema(implementation = GroupProblemResponse::class),
        )
      ],
  ),
  ApiResponse(
    responseCode = "500",
    description = "INTERNAL_ERROR 또는 GROUP_MEMBERSHIP_AMBIGUOUS",
    content =
      [
        Content(
          mediaType = "application/problem+json",
          schema = Schema(implementation = GroupProblemResponse::class),
        )
      ],
  ),
  ApiResponse(
    responseCode = "503",
    description = "SERVICE_UNAVAILABLE",
    content =
      [
        Content(
          mediaType = "application/problem+json",
          schema = Schema(implementation = GroupProblemResponse::class),
        )
      ],
  ),
)
interface GroupQueryApi {
  @Operation(
    operationId = "getGroupSummaries",
    summary = "멤버 ID 목록의 그룹 요약",
    description = "members는 요청 멤버만, totalMemberCount는 그룹 전체 인원입니다.",
  )
  @Parameter(
    name = "memberIds",
    `in` = ParameterIn.QUERY,
    required = true,
    style = ParameterStyle.FORM,
    explode = Explode.TRUE,
    array =
      ArraySchema(
        minItems = 1,
        maxItems = 100,
        uniqueItems = true,
        schema = Schema(type = "string", pattern = "^[a-z0-9]{10}$"),
      ),
  )
  @ApiResponse(
    responseCode = "200",
    description = "그룹별 요약",
    content =
      [
        Content(
          mediaType = "application/json",
          schema = Schema(implementation = GroupSummaryResponse::class),
        )
      ],
  )
  @GetMapping("/api/groups/summary", produces = ["application/json"])
  fun summaries(
    @Parameter(hidden = true) @RequestParam parameters: MultiValueMap<String, String>
  ): GroupSummaryResponse

  @Operation(
    operationId = "getMemberGroupDetail",
    summary = "멤버의 단일 그룹 상세",
    description = "미소속 404, 다건 500. 시각은 한국 시간 yyyy-MM-dd HH:mm입니다.",
  )
  @ApiResponse(
    responseCode = "404",
    description = "GROUP_MEMBERSHIP_NOT_FOUND",
    content =
      [
        Content(
          mediaType = "application/problem+json",
          schema = Schema(implementation = GroupProblemResponse::class),
        )
      ],
  )
  @ApiResponse(
    responseCode = "200",
    description = "단일 소속 상세",
    content =
      [
        Content(
          mediaType = "application/json",
          schema = Schema(implementation = MemberGroupDetailResponse::class),
        )
      ],
  )
  @GetMapping("/api/group/{memberId}", produces = ["application/json"])
  fun detail(
    @Parameter(required = true, schema = Schema(pattern = "^[a-z0-9]{10}$"))
    @PathVariable
    memberId: String
  ): ResponseEntity<MemberGroupDetailResponse>
}

