package task.group.infrastructure.persistence.group

import jakarta.persistence.EntityManager
import jakarta.persistence.Tuple
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Repository
import org.springframework.transaction.annotation.Isolation
import org.springframework.transaction.annotation.Transactional
import task.group.application.model.GroupMembershipRecord
import task.group.application.model.GroupReadSnapshot
import task.group.application.port.output.GroupSummaryReader
import task.group.application.port.output.MemberGroupReader

/** 두 조회를 같은 일관 읽기 스냅샷에서 수행한다(POL-GROUP-002). */
@Repository
class JpaGroupReader(private val entityManager: EntityManager) :
  GroupSummaryReader, MemberGroupReader {
  private val log = LoggerFactory.getLogger(javaClass)

  @Transactional(readOnly = true, isolation = Isolation.REPEATABLE_READ)
  override fun findSummaries(memberIds: List<String>): GroupReadSnapshot {
    val start = System.nanoTime()
    log.info("event=query.started queryName=group.summary requested={}", memberIds.size)
    val rows =
      entityManager
        .createQuery(SELECT + " where m.memberId in :ids", GroupMembershipRecord::class.java)
        .setParameter("ids", memberIds)
        .resultList
    val counts =
      if (rows.isEmpty()) emptyMap()
      else
        entityManager
          .createQuery(
            "select m.groupId as groupId, count(m) as total from GroupMembershipEntity m where m.groupId in :ids group by m.groupId",
            Tuple::class.java,
          )
          .setParameter("ids", rows.map { it.groupId }.distinct())
          .resultList
          .associate {
            it.get("groupId", String::class.java) to
              it.get("total", Long::class.javaObjectType).toLong()
          }
    log.info(
      "event=query.completed queryName=group.summary rows={} durationMs={}",
      rows.size,
      (System.nanoTime() - start) / 1_000_000,
    )
    return GroupReadSnapshot(rows, counts)
  }

  @Transactional(readOnly = true)
  override fun findByMemberId(memberId: String): List<GroupMembershipRecord> {
    val start = System.nanoTime()
    log.info("event=query.started queryName=group.detail")
    // 2행이면 이미 단일 소속 위반이다. 대표 행 선택이 아닌 다건 탐지용 제한이다.
    val rows =
      entityManager
        .createQuery(SELECT + " where m.memberId = :id", GroupMembershipRecord::class.java)
        .setParameter("id", memberId)
        .setMaxResults(2)
        .resultList
    log.info(
      "event=query.completed queryName=group.detail rows={} durationMs={}",
      rows.size,
      (System.nanoTime() - start) / 1_000_000,
    )
    return rows
  }

  private companion object {
    const val SELECT =
      "select new task.group.application.model.GroupMembershipRecord(m.memberId, g.id, g.name, m.joinedAt, g.pricing, m.permission) from GroupMembershipEntity m join GroupEntity g on g.id = m.groupId"
  }
}

package task.group.infrastructure.persistence.group

import jakarta.persistence.*
import java.time.Instant
import org.hibernate.annotations.JdbcTypeCode
import org.hibernate.type.SqlTypes
import task.group.domain.GroupPermissionType
import task.group.domain.GroupPricingType

/** 그룹 소유 데이터만 매핑한다(POL-DATA-003). */
@Entity
@Table(name = "user_group")
class GroupEntity(
  @Id @JdbcTypeCode(SqlTypes.CHAR) @Column(length = 10, nullable = false) val id: String,
  @Column(length = 100, nullable = false) val name: String,
  @Convert(converter = GroupPricingConverter::class)
  @Column(length = 20, nullable = false)
  val pricing: GroupPricingType,
  @Column(name = "created_at", nullable = false, columnDefinition = "timestamp(6)")
  val createdAt: Instant,
  @Column(name = "created_by", length = 50, nullable = false) val createdBy: String,
) {
  final override fun equals(other: Any?) =
    this === other || (other is GroupEntity && id == other.id)

  final override fun hashCode() = id.hashCode()
}

/** 외부 멤버 엔티티 관계 없이 식별자만 보유한다(POL-GROUP-001). */
@Entity
@Table(name = "group_membership")
class GroupMembershipEntity(
  @Id @GeneratedValue(strategy = GenerationType.IDENTITY) val id: Long? = null,
  @JdbcTypeCode(SqlTypes.CHAR)
  @Column(name = "group_id", length = 10, nullable = false)
  val groupId: String,
  @JdbcTypeCode(SqlTypes.CHAR)
  @Column(name = "member_id", length = 10, nullable = false)
  val memberId: String,
  @Convert(converter = GroupPermissionConverter::class)
  @Column(length = 20, nullable = false)
  val permission: GroupPermissionType,
  @Column(name = "joined_at", nullable = false, columnDefinition = "timestamp(6)")
  val joinedAt: Instant,
  @Column(name = "created_at", nullable = false, columnDefinition = "timestamp(6)")
  val createdAt: Instant,
  @Column(name = "created_by", length = 50, nullable = false) val createdBy: String,
) {
  final override fun equals(other: Any?) =
    this === other || (other is GroupMembershipEntity && id != null && id == other.id)

  final override fun hashCode() = GroupMembershipEntity::class.java.hashCode()
}

/** enum 상수 이름 대신 명시적 과금 code를 저장한다(POL-CODE-005). */
@Converter
class GroupPricingConverter : AttributeConverter<GroupPricingType, String> {
  override fun convertToDatabaseColumn(value: GroupPricingType?): String? = value?.code

  override fun convertToEntityAttribute(value: String?): GroupPricingType? =
    value?.let(GroupPricingType::fromCode)
}

/** enum 상수 이름 대신 명시적 권한 code를 저장한다(POL-CODE-005). */
@Converter
class GroupPermissionConverter : AttributeConverter<GroupPermissionType, String> {
  override fun convertToDatabaseColumn(value: GroupPermissionType?): String? = value?.code

  override fun convertToEntityAttribute(value: String?): GroupPermissionType? =
    value?.let(GroupPermissionType::fromCode)
}

package task.group.application.port.output

import task.group.application.model.GroupMembershipRecord
import task.group.application.model.GroupReadSnapshot

/** 여러 멤버의 소속과 그룹 인원을 한 읽기 트랜잭션에서 조회한다(POL-GROUP-002). */
fun interface GroupSummaryReader {
  fun findSummaries(memberIds: List<String>): GroupReadSnapshot
}

/** 다건 여부를 숨기지 않는 단일 멤버 소속 조회 경계(POL-GROUP-001). */
fun interface MemberGroupReader {
  fun findByMemberId(memberId: String): List<GroupMembershipRecord>
}

package task.group.application.port.input

import task.group.application.model.GroupMembershipRecord
import task.group.application.model.GroupSummaryView
import task.group.application.query.detail.MemberGroupDetailQuery
import task.group.application.query.summary.GroupSummaryQuery

/** HTTP 이외의 진입점도 재사용할 수 있는 조회 계약(POL-CQRS-004). */
fun interface GetGroupSummariesUseCase {
  fun execute(query: GroupSummaryQuery): List<GroupSummaryView>
}

/** 상세는 단일 소속을 반환하며 미소속·다건을 구분한다(POL-GROUP-001). */
fun interface GetMemberGroupDetailUseCase {
  fun execute(query: MemberGroupDetailQuery): GroupMembershipRecord
}

package task.group.application.exception

/** 원시 입력이나 데이터 내용을 예외 메시지에 담지 않는다(POL-API-002). */
class InvalidGroupQueryException : RuntimeException("그룹 조회 조건이 올바르지 않습니다.")

/** 미소속과 잘못된 HTTP 경로를 구분한다(POL-GROUP-001). */
class GroupMembershipNotFoundException : RuntimeException("그룹 소속을 찾을 수 없습니다.")

/** 복수 행을 대표 그룹으로 임의 선택하지 않는다(POL-GROUP-001). */
class GroupMembershipAmbiguousException : RuntimeException("단일 소속 조건에 맞지 않습니다.")

package task.group.presentation.query.response

import io.swagger.v3.oas.annotations.media.Schema
import io.swagger.v3.oas.annotations.media.Schema.RequiredMode.REQUIRED

/** 그룹별 요약 봉투(POL-GROUP-002). */
data class GroupSummaryResponse(
  @field:Schema(requiredMode = REQUIRED) val group: List<GroupSummaryItem>
)

/** 전체 인원과 요청 멤버를 구분한다(POL-GROUP-002). */
data class GroupSummaryItem(
  @field:Schema(requiredMode = REQUIRED, pattern = "^[a-z0-9]{10}$") val groupId: String,
  @field:Schema(requiredMode = REQUIRED, minLength = 1) val groupName: String,
  @field:Schema(requiredMode = REQUIRED, minimum = "0", description = "그룹 전체 소속 인원")
  val totalMemberCount: Long,
  @field:Schema(requiredMode = REQUIRED) val members: List<GroupMemberSummary>,
)

/** 권한 표시명은 응답에 포함하지 않는다(POL-CODE-005). */
data class GroupMemberSummary(
  @field:Schema(requiredMode = REQUIRED, pattern = "^[a-z0-9]{10}$") val memberId: String,
  @field:Schema(requiredMode = REQUIRED, description = "권한 code: Viewer, Editor, Admin")
  val permission: String,
)

/** 기존 6개 필드의 단일 상세 객체(POL-GROUP-001). */
data class MemberGroupDetailResponse(
  @field:Schema(requiredMode = REQUIRED, pattern = "^[a-z0-9]{10}$") val memberId: String,
  @field:Schema(requiredMode = REQUIRED, pattern = "^[a-z0-9]{10}$") val groupId: String,
  @field:Schema(requiredMode = REQUIRED, minLength = 1) val groupName: String,
  @field:Schema(
    requiredMode = REQUIRED,
    pattern = "^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}$",
    minLength = 16,
    maxLength = 16,
    example = "2026-08-15 13:00",
    description = "그룹 가입 시각. 한국 시간(Asia/Seoul), 분 단위",
  )
  val registeredDate: String,
  @field:Schema(requiredMode = REQUIRED, description = "과금 code: Free, Advanced, Premium")
  val pricing: String,
  @field:Schema(requiredMode = REQUIRED, description = "권한 code: Viewer, Editor, Admin")
  val permission: String,
)

/** 실제 오류 응답 계약(POL-API-002). */
data class GroupProblemResponse(
  @field:Schema(requiredMode = REQUIRED, example = "about:blank") val type: String,
  @field:Schema(requiredMode = REQUIRED) val title: String,
  @field:Schema(requiredMode = REQUIRED) val status: Int,
  @field:Schema(requiredMode = REQUIRED) val detail: String,
  @field:Schema(requiredMode = REQUIRED) val instance: String,
  @field:Schema(requiredMode = REQUIRED) val code: String,
)

package task.group.presentation.error

import com.fasterxml.jackson.annotation.JsonInclude
import java.net.URI
import org.springframework.http.ProblemDetail

/** about:blank type도 필수 필드로 직렬화한다(POL-API-002). */
class GroupProblemDetail(source: ProblemDetail) : ProblemDetail(source) {
  @JsonInclude(JsonInclude.Include.ALWAYS)
  override fun getType(): URI = super.getType() ?: URI.create("about:blank")
}

package task.group.presentation.error

import org.springframework.dao.DataAccessResourceFailureException
import org.springframework.http.*
import org.springframework.transaction.CannotCreateTransactionException
import org.springframework.web.bind.MethodArgumentNotValidException
import org.springframework.web.bind.annotation.ExceptionHandler
import org.springframework.web.bind.annotation.RestControllerAdvice
import org.springframework.web.context.request.WebRequest
import org.springframework.web.method.annotation.HandlerMethodValidationException
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler
import task.group.application.exception.*

/** 의미 있는 예외를 고정 오류 계약으로 매핑한다(POL-API-002, POL-GROUP-001). */
@RestControllerAdvice
class ProblemDetailsExceptionHandler : ResponseEntityExceptionHandler() {
  @ExceptionHandler(InvalidGroupQueryException::class)
  fun invalid(ex: InvalidGroupQueryException) = problem(ErrorCode.VALIDATION_FAILED, ex)

  @ExceptionHandler(GroupMembershipNotFoundException::class)
  fun missing(ex: GroupMembershipNotFoundException) =
    problem(ErrorCode.GROUP_MEMBERSHIP_NOT_FOUND, ex)

  @ExceptionHandler(GroupMembershipAmbiguousException::class)
  fun ambiguous(ex: GroupMembershipAmbiguousException) =
    problem(ErrorCode.GROUP_MEMBERSHIP_AMBIGUOUS, ex)

  @ExceptionHandler(
    DataAccessResourceFailureException::class,
    CannotCreateTransactionException::class,
  )
  fun unavailable(ex: Exception) = problem(ErrorCode.SERVICE_UNAVAILABLE, ex)

  @ExceptionHandler(Exception::class)
  fun unexpected(ex: Exception) = problem(ErrorCode.INTERNAL_ERROR, ex)

  override fun handleExceptionInternal(
    ex: Exception,
    body: Any?,
    headers: HttpHeaders,
    statusCode: HttpStatusCode,
    request: WebRequest,
  ): ResponseEntity<Any>? {
    val code =
      when (ex) {
        is MethodArgumentNotValidException,
        is HandlerMethodValidationException -> ErrorCode.VALIDATION_FAILED
        else -> ErrorCode.of(statusCode)
      }
    return super.handleExceptionInternal(ex, problem(code, ex), headers, statusCode, request)
  }

  private fun problem(code: ErrorCode, ex: Exception): ProblemDetail {
    SafeErrorLog.record(code, ex)
    return GroupProblemDetail(
      ProblemDetail.forStatusAndDetail(HttpStatusCode.valueOf(code.status), code.description)
        .apply {
          title = code.codeName
          setProperty(CODE, code.code)
        }
    )
  }

  companion object {
    const val CODE = "code"
  }
}

