package task.group

import java.time.Instant
import kotlin.test.*
import org.junit.jupiter.api.Test
import task.group.application.exception.*
import task.group.application.model.*
import task.group.application.port.output.*
import task.group.application.query.detail.*
import task.group.application.query.summary.*
import task.group.domain.*

/** 순수 조회와 다건 방어, 입력 범위를 검증한다(POL-GROUP-001·002). */
class GroupQueryTests {
  private fun row(member: String = "member0001", group: String = "group00001") =
    GroupMembershipRecord(
      member,
      group,
      "합성 그룹",
      Instant.parse("2026-08-15T04:00:59.123456Z"),
      GroupPricingType.FREE,
      GroupPermissionType.VIEWER,
    )

  @Test
  fun `상세는 미소속 단일 다건을 구분하고 대표 행을 임의로 고르지 않는다`() {
    val query = MemberGroupDetailQuery("member0001")
    assertFailsWith<GroupMembershipNotFoundException> {
      MemberGroupDetailQueryHandler(MemberGroupReader { emptyList() }).execute(query)
    }
    assertEquals(
      row(),
      MemberGroupDetailQueryHandler(MemberGroupReader { listOf(row()) }).execute(query),
    )
    assertFailsWith<GroupMembershipAmbiguousException> {
      MemberGroupDetailQueryHandler(MemberGroupReader { listOf(row(), row(group = "group00002")) })
        .execute(query)
    }
  }

  @Test
  fun `요청 멤버만 묶고 전체 인원과 정렬은 별도로 보존한다`() {
    val rows = listOf(row("member0002"), row("member0001"))
    val result =
      GroupSummaryQueryHandler(
          GroupSummaryReader { GroupReadSnapshot(rows, mapOf("group00001" to 9L)) }
        )
        .execute(GroupSummaryQuery(listOf("member0002", "member0001")))
    assertEquals(9, result.single().totalMemberCount)
    assertEquals(listOf("member0001", "member0002"), result.single().members.map { it.memberId })
  }

  @Test
  fun `summary도 같은 멤버의 서로 다른 그룹 소속을 오류로 인지한다`() {
    assertFailsWith<GroupMembershipAmbiguousException> {
      GroupSummaryQueryHandler(
          GroupSummaryReader {
            GroupReadSnapshot(listOf(row(), row(group = "group00002")), emptyMap())
          }
        )
        .execute(GroupSummaryQuery(listOf("member0001")))
    }
  }

  @Test
  fun `누락 공백 중복 잘못된 식별자와 101개를 보정하지 않는다`() {
    val invalid =
      listOf(
        emptyList(),
        listOf(""),
        listOf(" "),
        listOf("MEMBER0001"),
        listOf("member0001", "member0001"),
        (1..101).map { "m" + it.toString().padStart(9, '0') },
      )
    invalid.forEach { ids ->
      assertFailsWith<InvalidGroupQueryException> { GroupSummaryQuery(ids) }
    }
    assertEquals(
      100,
      GroupSummaryQuery((1..100).map { "m" + it.toString().padStart(9, '0') }).memberIds.size,
    )
  }

  @Test
  fun `코드의 내부 메타데이터와 정확한 문자열 변환을 검증한다`() {
    GroupPermissionType.entries.forEach {
      assertEquals(it, GroupPermissionType.fromCode(it.code))
      assertTrue(it.codeName.isNotBlank())
      assertTrue(it.description.isNotBlank())
      assertEquals("ACTIVE", it.status)
    }
    GroupPricingType.entries.forEach {
      assertEquals(it, GroupPricingType.fromCode(it.code))
      assertTrue(it.codeName.isNotBlank())
      assertTrue(it.description.isNotBlank())
    }
    assertFailsWith<IllegalArgumentException> { GroupPricingType.fromCode("free") }
    assertFailsWith<IllegalArgumentException> { GroupPermissionType.fromCode("unknown") }
  }
}

package task.group

import jakarta.persistence.EntityManagerFactory
import java.time.Instant
import java.util.concurrent.Callable
import java.util.concurrent.Executors
import kotlin.test.*
import org.hibernate.SessionFactory
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.extension.ExtendWith
import org.mockito.Mockito.*
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.boot.test.system.CapturedOutput
import org.springframework.boot.test.system.OutputCaptureExtension
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc
import org.springframework.context.annotation.Import
import org.springframework.dao.DataIntegrityViolationException
import org.springframework.jdbc.core.JdbcTemplate
import org.springframework.test.context.DynamicPropertyRegistry
import org.springframework.test.context.DynamicPropertySource
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.get
import org.springframework.transaction.support.TransactionSynchronizationManager
import task.group.application.model.GroupMembershipRecord
import task.group.application.query.summary.GroupSummaryQuery
import task.group.application.query.summary.GroupSummaryQueryHandler
import task.group.domain.*
import task.group.infrastructure.persistence.group.JpaGroupReader
import task.group.support.*

/** 실제 MariaDB·운영 HTTP 경계의 정합성을 검증한다(POL-TEST-005·006). */
@SpringBootTest(
  properties =
    [TestProperties.NO_LOCAL_SECRETS, "spring.jpa.properties.hibernate.generate_statistics=true"]
)
@AutoConfigureMockMvc
@Import(TestcontainersConfiguration::class, GroupSqlObservationConfiguration::class)
@ExtendWith(OutputCaptureExtension::class)
class GroupQueryIntegrationTests {
  @Autowired lateinit var mvc: MockMvc
  @Autowired lateinit var jdbc: JdbcTemplate
  @Autowired lateinit var emf: EntityManagerFactory
  @Autowired lateinit var handler: GroupSummaryQueryHandler
  @MockitoSpyBean lateinit var reader: JpaGroupReader

  @BeforeEach
  fun setup() {
    reset(reader)
    jdbc.update("delete from group_membership")
    jdbc.update("delete from user_group")
    jdbc.update(
      "insert into user_group values ('group00001','합성 그룹','Premium','2026-08-01 00:00:00.123456','seed'),('group00002','다른 그룹','Free','2026-08-01 00:00:00.123456','seed')"
    )
    insert("member0001", "group00001")
    insert("member0002", "group00001")
  }

  private fun insert(member: String, group: String) =
    jdbc.update(
      "insert into group_membership(group_id,member_id,permission,joined_at,created_at,created_by) values (?,?,'Editor','2026-08-15 15:30:59.123456','2026-08-15 04:00:00.654321','seed')",
      group,
      member,
    )

  private fun request(path: String) =
    mvc.get(path) {
      header("X-Internal-Service-Id", "member-service")
      header("X-Internal-Service-Key", TestProperties.internalKey)
      header("X-Request-Id", "group-query-test")
    }

  @Test
  fun `summary는 요청 소속과 전체 인원을 구분하고 실제 두 쿼리로 처리한다`() {
    val stats = emf.unwrap(SessionFactory::class.java).statistics
    stats.clear()
    val result = handler.execute(GroupSummaryQuery(listOf("member0001")))
    assertEquals(2, result.single().totalMemberCount)
    assertEquals(1, result.single().members.size)
    assertEquals(2, stats.prepareStatementCount)
    assertFalse(TransactionSynchronizationManager.isActualTransactionActive())
    stats.clear()
    handler.execute(GroupSummaryQuery((1..100).map { "m" + it.toString().padStart(9, '0') }))
    assertTrue(stats.prepareStatementCount <= 2)
    request("/api/groups/summary?memberIds=member0001").andExpect {
      status { isOk() }
      jsonPath("$.group[0].totalMemberCount") { value(2) }
      jsonPath("$.group[0].members[0].permissionName") { doesNotExist() }
    }
  }

  @Test
  fun `상세는 기존 필드와 한국 시각을 반환하고 DB 마이크로초는 보존한다`() {
    val response =
      request("/api/group/member0001")
        .andExpect {
          status { isOk() }
          jsonPath("$.registeredDate") { value("2026-08-16 00:30") }
          jsonPath("$.permission") { value("Editor") }
          jsonPath("$.permissionName") { doesNotExist() }
          jsonPath("$.groups") { doesNotExist() }
          header { string("X-Request-Id", "group-query-test") }
        }
        .andReturn()
        .response
    val mapper = tools.jackson.databind.json.JsonMapper.builder().build()
    assertEquals(
      setOf("memberId", "groupId", "groupName", "registeredDate", "pricing", "permission"),
      mapper.readTree(response.contentAsByteArray).propertyNames().toSet(),
    )
    assertEquals(
      123456,
      jdbc.queryForObject(
        "select microsecond(joined_at) from group_membership where member_id='member0001'",
        Int::class.java,
      ),
    )
    assertEquals(
      "timestamp",
      jdbc.queryForObject(
        "select data_type from information_schema.columns where table_schema=database() and table_name='group_membership' and column_name='joined_at'",
        String::class.java,
      ),
    )
  }

  @Test
  fun `단일 소속 제약은 다른 그룹과 동시 입력도 거부한다`() {
    assertFailsWith<DataIntegrityViolationException> { insert("member0001", "group00002") }
    val pool = Executors.newFixedThreadPool(2)
    try {
      val futures =
        pool.invokeAll(
          listOf("group00001", "group00002").map { group ->
            Callable { runCatching { insert("member0003", group) }.isSuccess }
          }
        )
      assertEquals(1, futures.count { it.get() })
      assertEquals(
        1,
        jdbc.queryForObject(
          "select count(*) from group_membership where member_id='member0003'",
          Int::class.java,
        ),
      )
    } finally {
      pool.shutdownNow()
    }
  }

  @Test
  fun `다건 조회는 500과 전용 예외 ERROR를 남기고 식별자는 로그에 넣지 않는다`(output: CapturedOutput) {
    val row =
      GroupMembershipRecord(
        "privateid1",
        "group00001",
        "비공개 이름",
        Instant.now(),
        GroupPricingType.FREE,
        GroupPermissionType.VIEWER,
      )
    doReturn(listOf(row, row.copy(groupId = "group00002")))
      .`when`(reader)
      .findByMemberId("privateid1")
    request("/api/group/privateid1").andExpect {
      status { isInternalServerError() }
      jsonPath("$.code") { value("GROUP_MEMBERSHIP_AMBIGUOUS") }
      jsonPath("$.type") { value("about:blank") }
    }
    assertTrue(output.out.contains("event=exception.handled"))
    assertTrue(output.out.contains("GroupMembershipAmbiguousException"))
    assertTrue(output.out.contains("ERROR"))
    assertFalse(output.out.contains("privateid1"))
    assertFalse(output.out.contains(TestProperties.internalKey))
    assertNull(org.slf4j.MDC.get("requestId"))
  }

  @Test
  fun `미소속 경로404 입력오류와 인증오류를 구분한다`() {
    request("/api/group/member9999").andExpect {
      status { isNotFound() }
      jsonPath("$.code") { value("GROUP_MEMBERSHIP_NOT_FOUND") }
    }
    request("/api/missing").andExpect {
      status { isNotFound() }
      jsonPath("$.code") { value("NOT_FOUND") }
    }
    request("/api/groups/summary?memberIds=member0001&memberIds=member0001").andExpect {
      status { isBadRequest() }
      jsonPath("$.code") { value("VALIDATION_FAILED") }
    }
    request("/api/groups/summary?memberIds=%20").andExpect { status { isBadRequest() } }
    mvc.get("/api/group/member0001").andExpect { status { isForbidden() } }
  }

  @Test
  fun `두 쿼리 사이에 다른 연결이 소속을 추가해도 같은 스냅샷을 읽는다`() {
    val pool = Executors.newSingleThreadExecutor()
    var observed = false
    GroupSqlObservation.observer.set { sql ->
      assertTrue(TransactionSynchronizationManager.isActualTransactionActive())
      assertTrue(TransactionSynchronizationManager.isCurrentTransactionReadOnly())
      assertEquals(
        java.sql.Connection.TRANSACTION_REPEATABLE_READ,
        TransactionSynchronizationManager.getCurrentTransactionIsolationLevel(),
      )
      if (sql.contains("count(")) {
        GroupSqlObservation.observer.remove()
        pool.submit { insert("member0003", "group00001") }.get()
        observed = true
      }
    }
    try {
      val result = handler.execute(GroupSummaryQuery(listOf("member0001")))
      assertTrue(observed)
      assertEquals(2, result.single().totalMemberCount)
      assertEquals(3, jdbc.queryForObject("select count(*) from group_membership", Int::class.java))
      assertFalse(TransactionSynchronizationManager.isActualTransactionActive())
    } finally {
      GroupSqlObservation.observer.remove()
      pool.shutdownNow()
    }
  }

  @Test
  fun `알 수 없는 저장 코드는 500이며 원문 값이 예외 로그에 나오지 않는다`(output: CapturedOutput) {
    jdbc.update("update user_group set pricing='invalid-sensitive' where id='group00001'")
    request("/api/group/member0001").andExpect {
      status { isInternalServerError() }
      jsonPath("$.code") { value("INTERNAL_ERROR") }
    }
    assertTrue(output.out.contains("event=exception.handled"))
    assertFalse(output.out.contains("invalid-sensitive"))
  }

  companion object {
    @JvmStatic
    @DynamicPropertySource
    fun properties(registry: DynamicPropertyRegistry) = TestProperties.register(registry)
  }
}

package task.group

import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.springframework.boot.test.context.runner.ApplicationContextRunner
import org.springframework.mock.web.MockFilterChain
import org.springframework.mock.web.MockHttpServletRequest
import org.springframework.mock.web.MockHttpServletResponse
import task.group.infrastructure.configuration.InternalServiceConfiguration
import task.group.infrastructure.configuration.InternalServiceFilter
import task.group.support.TestProperties
import tools.jackson.databind.json.JsonMapper

/** 내부 호출 키가 없을 때 열린 상태로 기동하지 않는지 확인한다(POL-SEC-001). */
class InternalServiceConfigurationTests {
  @Test
  fun `health 원문 접두사로 다른 정규화 경로의 키 검사를 건너뛰지 않는다`() {
    val request =
      MockHttpServletRequest("GET", "/actuator/health/../../v3/api-docs").apply {
        servletPath = "/v3/api-docs"
      }
    val response = MockHttpServletResponse()
    val chain = MockFilterChain()
    InternalServiceFilter(
        mapOf(
          "member-service" to
            task.group.infrastructure.configuration.InternalCallerProperties(
              TestProperties.internalKey
            )
        ),
        JsonMapper.builder().build(),
      )
      .doFilter(request, response, chain)
    assertThat(response.status).isEqualTo(403)
    assertThat(chain.request).isNull()
  }

  @Test
  fun `키가 없으면 기동 실패하고 키가 있으면 필터를 등록한다`() {
    val runner =
      ApplicationContextRunner()
        .withUserConfiguration(InternalServiceConfiguration::class.java)
        .withBean(JsonMapper::class.java, { JsonMapper.builder().build() })
    runner.run { assertThat(it).hasFailed() }
    runner
      .withPropertyValues(
        "task.internal-service.clients.member-service.key=${TestProperties.internalKey}"
      )
      .run {
        assertThat(it).hasNotFailed().hasBean("internalServiceFilter")
      }
  }

  @Test
  fun `호출자와 키를 함께 검사하고 중복 헤더 및 선택 IP 범위를 거부한다`() {
    val otherKey = TestProperties.internalKey.reversed()
    val filter =
      InternalServiceFilter(
        mapOf(
          "member-service" to
            task.group.infrastructure.configuration.InternalCallerProperties(
              TestProperties.internalKey,
              listOf("10.20.0.0/16"),
            ),
          "other-service" to
            task.group.infrastructure.configuration.InternalCallerProperties(
              otherKey,
              listOf("2001:db8::/32"),
            ),
        ),
        JsonMapper.builder().build(),
      )
    fun request(ids: List<String>, keys: List<String>, remote: String): Int {
      val request =
        MockHttpServletRequest("GET", "/api/group/member0001").apply {
          remoteAddr = remote
          ids.forEach { addHeader("X-Internal-Service-Id", it) }
          keys.forEach { addHeader("X-Internal-Service-Key", it) }
          addHeader("X-Forwarded-For", "10.20.1.2")
        }
      val response = MockHttpServletResponse()
      filter.doFilter(request, response, MockFilterChain())
      return response.status
    }
    assertThat(request(listOf("member-service"), listOf(TestProperties.internalKey), "10.20.1.2"))
      .isEqualTo(200)
    assertThat(request(listOf("member-service"), listOf(TestProperties.internalKey), "10.21.1.2"))
      .isEqualTo(403)
    assertThat(request(listOf("other-service"), listOf(otherKey), "2001:db8::1")).isEqualTo(200)
    assertThat(request(listOf("other-service"), listOf(TestProperties.internalKey), "2001:db8::1"))
      .isEqualTo(403)
    assertThat(request(listOf("unknown"), listOf(TestProperties.internalKey), "10.20.1.2"))
      .isEqualTo(403)
    assertThat(request(emptyList(), listOf(TestProperties.internalKey), "10.20.1.2")).isEqualTo(403)
    assertThat(
        request(
          listOf("member-service", "member-service"),
          listOf(TestProperties.internalKey),
          "10.20.1.2",
        )
      )
      .isEqualTo(403)
    assertThat(
        request(
          listOf("member-service"),
          listOf(TestProperties.internalKey, TestProperties.internalKey),
          "10.20.1.2",
        )
      )
      .isEqualTo(403)
    for (bad in listOf("localhost/32", "256.0.0.1/32", "10.0.0.1/33", "::1/129", "10.0.0.1")) {
      kotlin.test.assertFailsWith<IllegalArgumentException> {
        task.group.infrastructure.configuration.InternalCallerProperties(
          TestProperties.internalKey,
          listOf(bad),
        )
      }
    }
  }
}

