package task.group.contract

import java.nio.file.Files
import java.nio.file.Path
import kotlin.test.*
import org.junit.jupiter.api.Test
import org.mockito.Mockito.doReturn
import org.mockito.Mockito.reset
import org.springframework.beans.factory.annotation.Autowired
import org.springframework.boot.autoconfigure.AutoConfigurationPackage
import org.springframework.boot.autoconfigure.EnableAutoConfiguration
import org.springframework.boot.test.context.SpringBootTest
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc
import org.springframework.context.annotation.ComponentScan
import org.springframework.context.annotation.Configuration
import org.springframework.context.annotation.Import
import org.springframework.context.annotation.Profile
import org.springframework.test.context.ActiveProfiles
import org.springframework.test.context.DynamicPropertyRegistry
import org.springframework.test.context.DynamicPropertySource
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean
import org.springframework.test.web.servlet.MockMvc
import org.springframework.test.web.servlet.get
import task.group.infrastructure.persistence.group.JpaGroupReader
import task.group.support.*
import tools.jackson.databind.json.JsonMapper

/** 테스트 전용 Controller가 공유 명세에 섞이지 않는 별도 문맥(POL-TEST-007). */
@Configuration(proxyBeanMethods = false)
@Profile("openapi-contract")
@EnableAutoConfiguration
@AutoConfigurationPackage(basePackages = ["task.group.infrastructure.persistence"])
@ComponentScan("task.group.application", "task.group.infrastructure", "task.group.presentation")
class GroupContractApplication

/** 실제 Controller·DB·시드와 내부 인증을 거쳐 명세를 검증한다(POL-TEST-007). */
@SpringBootTest(
  classes = [GroupContractApplication::class],
  properties = [TestProperties.NO_LOCAL_SECRETS],
)
@AutoConfigureMockMvc
@ActiveProfiles("local", "openapi-contract")
@Import(TestcontainersConfiguration::class)
class GroupOpenApiContractTests {
  @Autowired lateinit var mvc: MockMvc
  @Autowired lateinit var json: JsonMapper
  @MockitoSpyBean lateinit var reader: JpaGroupReader

  private fun get(path: String, authenticated: Boolean = true) =
    mvc
      .get(path) {
        if (authenticated) {
          header("X-Internal-Service-Id", "member-service")
          header("X-Internal-Service-Key", TestProperties.internalKey)
        }
      }
      .andReturn()
      .response

  @Test
  fun `명세와 실제 성공 오류 응답을 검사하고 결정적 스냅샷을 생성한다`() {
    val spec = json.readTree(get("/v3/api-docs").contentAsByteArray)
    assertEquals(
      setOf("/api/groups/summary", "/api/group/{memberId}"),
      spec.path("paths").propertyNames().toSet(),
    )
    assertEquals(
      setOf("internalServiceId", "internalServiceKey"),
      spec.path("security").single().propertyNames().toSet(),
    )
    val contract = OpenApiContract(spec, json)
    contract.validateDocument()
    val detailSchema = spec.path("components").path("schemas").path("MemberGroupDetailResponse")
    assertEquals(
      setOf("memberId", "groupId", "groupName", "registeredDate", "pricing", "permission"),
      detailSchema.path("properties").propertyNames().toSet(),
    )
    assertFalse(detailSchema.path("properties").path("registeredDate").has("format"))
    for ((url, path, expected) in
      listOf(
        Triple("/api/groups/summary?memberIds=tu3fgxd45k", "/api/groups/summary", 200),
        Triple("/api/group/tu3fgxd45k", "/api/group/{memberId}", 200),
        Triple("/api/groups/summary?memberIds=%20", "/api/groups/summary", 400),
        Triple("/api/group/k2m9x0p1q3", "/api/group/{memberId}", 404),
      )) {
      val response = get(url)
      assertEquals(expected, response.status)
      val media = if (expected == 200) "application/json" else "application/problem+json"
      assertTrue(contract.errors(path, expected, media, response.contentAsString).isEmpty())
    }
    val forbidden = get("/api/group/tu3fgxd45k", false)
    assertEquals(403, forbidden.status)
    assertTrue(
      contract
        .errors("/api/group/{memberId}", 403, "application/problem+json", forbidden.contentAsString)
        .isEmpty()
    )
    val rows = reader.findByMemberId("tu3fgxd45k")
    doReturn(rows + rows).`when`(reader).findByMemberId("tu3fgxd45k")
    try {
      val ambiguous = get("/api/group/tu3fgxd45k")
      assertEquals(500, ambiguous.status)
      assertTrue(
        contract
          .errors(
            "/api/group/{memberId}",
            500,
            "application/problem+json",
            ambiguous.contentAsString,
          )
          .isEmpty()
      )
    } finally {
      reset(reader)
    }

    org.mockito.Mockito.doThrow(
        org.springframework.dao.DataAccessResourceFailureException("synthetic")
      )
      .`when`(reader)
      .findByMemberId("tu3fgxd45k")
    try {
      val unavailable = get("/api/group/tu3fgxd45k")
      assertEquals(503, unavailable.status)
      assertTrue(
        contract
          .errors(
            "/api/group/{memberId}",
            503,
            "application/problem+json",
            unavailable.contentAsString,
          )
          .isEmpty()
      )
    } finally {
      reset(reader)
    }
    val examples =
      Regex("~~~json\\s*([\\s\\S]*?)~~~")
        .findAll(Files.readString(Path.of("docs/api.md")))
        .map { it.groupValues[1] }
        .toList()
    assertEquals(2, examples.size)
    assertTrue(
      contract.errors("/api/groups/summary", 200, "application/json", examples[0]).isEmpty()
    )
    assertTrue(
      contract.errors("/api/group/{memberId}", 200, "application/json", examples[1]).isEmpty()
    )
    val bytes = contract.canonicalBytes()
    assertContentEquals(bytes, contract.canonicalBytes())
    val output = Path.of(requireNotNull(System.getProperty("task.openapi.output")))
    Files.createDirectories(output.parent)
    Files.write(output, bytes)
  }

  companion object {
    @JvmStatic
    @DynamicPropertySource
    fun properties(registry: DynamicPropertyRegistry) {
      TestProperties.register(registry)
      registry.add("spring.flyway.locations") {
        "classpath:db/migration/mariadb,classpath:db/seed/local"
      }
    }
  }
}

package task.group.contract

import com.networknt.org.apache.commons.validator.routines.EmailValidator
import com.networknt.schema.InputFormat
import com.networknt.schema.SchemaLocation
import com.networknt.schema.SchemaRegistry
import com.networknt.schema.SpecificationVersion
import com.networknt.schema.dialect.Dialect
import com.networknt.schema.dialect.Dialects
import com.networknt.schema.format.EmailFormat
import kotlin.test.assertTrue
import tools.jackson.databind.JsonNode
import tools.jackson.databind.json.JsonMapper
import tools.jackson.databind.node.ObjectNode

/** OpenAPI 3.1 명세와 그 응답 스키마를 같은 Jackson 3으로 검사한다(POL-TEST-007). */
class OpenApiContract(private val spec: JsonNode, private val mapper: JsonMapper) {
  // .invalid는 발송 불가 합성 데이터다. 로컬 부분 검사는 유지하고 이 도메인만 허용한다.
  private val registry =
    SchemaRegistry.withDialect(
      Dialect.builder(Dialects.getOpenApi31())
        .format(
          EmailFormat(
            object : EmailValidator(false, false) {
              override fun isValidDomain(domain: String): Boolean =
                domain.equals("example.invalid", ignoreCase = true) || super.isValidDomain(domain)
            }
          )
        )
        .build()
    )

  /** 공식 메타스키마는 클래스패스에 고정하여 테스트 중 네트워크 조회를 하지 않는다. */
  fun validateDocument() {
    val meta =
      SchemaRegistry.withDefaultDialect(SpecificationVersion.DRAFT_2020_12) { builder ->
          builder.schemaIdResolvers {
            it.mapPrefix("https://spec.openapis.org/oas/3.1", "classpath:openapi-meta")
          }
        }
        .getSchema(SchemaLocation.of("https://spec.openapis.org/oas/3.1/schema-base/2022-10-07"))
    val errors = meta.validate(spec.toString(), InputFormat.JSON)
    assertTrue(errors.isEmpty(), "OpenAPI 메타스키마 오류: ${errors.map { it.keyword }}")
  }

  /** 선택한 HTTP 상태·매체 유형의 스키마로 응답을 검증한다. 값은 실패 메시지에 넣지 않는다. */
  fun errors(path: String, status: Int, mediaType: String, body: String): List<String> {
    val schema =
      spec
        .path("paths")
        .path(path)
        .path("get")
        .path("responses")
        .path(status.toString())
        .path("content")
        .path(mediaType)
        .path("schema")
    require(schema.isObject) { "응답 계약이 없습니다: $path $status $mediaType" }
    val root = schema.deepCopy() as ObjectNode
    root.set("components", spec.path("components"))
    return registry
      .getSchema(SchemaLocation.of("urn:group:response"), root)
      .validate(body, InputFormat.JSON) { context ->
        context.executionConfig { it.formatAssertionsEnabled(true) }
      }
      .map { "${it.keyword}:${it.instanceLocation}" }
  }

  /** 환경마다 달라지는 서버 URL만 정규화하고 배열 순서는 보존한다(POL-TEST-007). */
  fun canonicalBytes(): ByteArray = canonicalBytes(spec)

  fun canonicalBytes(source: JsonNode): ByteArray {
    val copy = source.deepCopy() as ObjectNode
    copy.path("servers").forEach { (it as ObjectNode).put("url", "/") }
    return (mapper
        .writerWithDefaultPrettyPrinter()
        .writeValueAsString(sorted(copy))
        .replace("\r\n", "\n") + "\n")
      .toByteArray(Charsets.UTF_8)
  }

  private fun sorted(node: JsonNode): JsonNode =
    when {
      node.isObject ->
        mapper.createObjectNode().apply {
          node.propertyNames().sorted().forEach { set(it, sorted(node.path(it))) }
        }
      node.isArray -> mapper.createArrayNode().apply { node.forEach { add(sorted(it)) } }
      else -> node
    }
}

